// Binary Search Tree example by @SleepyRoy

struct Empty {}

struct Node[T] {
	value T
	left  Tree[T]
	right Tree[T]
}

type Tree[T] = Empty | Node[T]

// return size(number of nodes) of BST
fn (tree Tree[T]) size[T]() int {
	return match tree {
		Empty { 0 }
		Node[T] { 1 + tree.left.size() + tree.right.size() }
	}
}

// insert a value to BST
fn (tree Tree[T]) insert[T](x T) Tree[T] {
	return match tree {
		Empty {
			Node[T]{x, tree, tree}
		}
		Node[T] {
			if x == tree.value {
				tree
			} else if x < tree.value {
				Node[T]{
					...tree
					left: tree.left.insert(x)
				}
			} else {
				Node[T]{
					...tree
					right: tree.right.insert(x)
				}
			}
		}
	}
}

// whether able to find a value in BST
fn (tree Tree[T]) search[T](x T) bool {
	return match tree {
		Empty {
			false
		}
		Node[T] {
			if x == tree.value {
				true
			} else if x < tree.value {
				tree.left.search(x)
			} else {
				tree.right.search(x)
			}
		}
	}
}

// find the minimal value of a BST
fn (tree Tree[T]) min[T]() T {
	return match tree {
		Empty {
			T(1e9)
		}
		Node[T] {
			if tree.value < tree.left.min() {
				tree.value
			} else {
				tree.left.min()
			}
		}
	}
}

// delete a value in BST (if nonexistent do nothing)
fn (tree Tree[T]) delete[T](x T) Tree[T] {
	return match tree {
		Empty {
			tree
		}
		Node[T] {
			if tree.left !is Empty && tree.right !is Empty {
				if x < tree.value {
					Node[T]{
						...tree
						left: tree.left.delete(x)
					}
				} else if x > tree.value {
					Node[T]{
						...tree
						right: tree.right.delete(x)
					}
				} else {
					Node[T]{
						...tree
						value: tree.right.min()
						right: tree.right.delete(tree.right.min())
					}
				}
			} else if tree.left !is Empty {
				if x == tree.value {
					tree.left
				} else {
					Node[T]{
						...tree
						left: tree.left.delete(x)
					}
				}
			} else {
				if x == tree.value {
					tree.right
				} else {
					Node[T]{
						...tree
						right: tree.right.delete(x)
					}
				}
			}
		}
	}
}

fn main() {
	mut tree := Tree[f64](Empty{})
	vals := [0.2, 0.0, 0.5, 0.3, 0.6, 0.8, 0.9, 1.0, 0.1, 0.4, 0.7]
	for i in vals {
		tree = tree.insert(i)
	}
	println('[1] after insertion tree size is ${tree.size()}') // 11
	del_vals := [-0.3, 0.0, 0.3, 0.6, 1.0, 1.5]
	for i in del_vals {
		tree = tree.delete(i)
	}
	print('[2] after deletion tree size is ${tree.size()}, ') // 7
	print('and these elements were deleted: ') // 0.0 0.3 0.6 1.0
	for i in vals {
		if !tree.search(i) {
			print('${i} ')
		}
	}
	println('')
}

import os
import term

// For a more detailed description of the brainfuck language, see:
// https://en.wikipedia.org/wiki/Brainfuck
// http://brainfuck.org/brainfuck.html ,
// http://brainfuck.org/epistle.html ,
// http://www.hevanet.com/cristofd/brainfuck/ .

const show_state = os.getenv('VERBOSE') != ''

struct BFState {
mut:
	pc      u16    // program counter (PC) register
	address u16    // a 16-bit address register, serving as an index to the memory below
	program string // the BF program
	memory  []u8 = []u8{len: 65536} // we have 2^16 bytes of memory
	targets map[int]int // a mapping for the program address of a `[` to its corresponding `]`, and from a `]` to its corresponding opening `[`.
}

fn BFState.new(program string) &BFState {
	mut state := &BFState{
		program: program
	}
	state.find_matching_pairs()
	return state
}

// show the current state of an BF interpreter. Useful for debugging.
fn (state &BFState) show(suffix string) {
	mut max_non_zero_address := -1
	for i := state.memory.len - 1; i >= 0; i-- {
		if state.memory[i] != 0 {
			max_non_zero_address = i
			break
		}
	}
	println('PC: ${state.pc:04} | Address: ${state.address:04} | Memory: ${state.memory#[0..max_non_zero_address + 1]:-40s} | Memory[Address]: ${state.memory#[state.address..state.address + 1]:-10s} | ${suffix}')
}

// find_matching_pairs fills in the `targets` mapping for all pairs of `[` and `]`,
// so that when interpreting, we would not have to search for them anymore.
fn (mut state BFState) find_matching_pairs() {
	mut stack := []int{}
	for i in 0 .. state.program.len {
		pi := state.program[i]
		match pi {
			`[` {
				stack << i
			}
			`]` {
				if stack.len == 0 {
					eprintln('> unmatched `]` found in the program, at position: ${i}')
					eprintln('program so far:')
					eprintln(state.program#[0..i + 1])
					exit(1)
				}
				pc := stack.pop()
				state.targets[pc] = i + 1
				state.targets[i] = pc + 1
				// eprintln('>>> found `[` at i ${i}; pc: ${pc}')
			}
			else {}
		}
	}
	if stack.len > 0 {
		eprintln('> found ${stack.len} unmatched `[`:')
		for i in stack {
			eprintln('  `[` at position: ${i}, program so far: `${state.program#[0..i + 1]}`')
		}
		exit(1)
	}
}

@[noreturn]
fn (state &BFState) panic_for_bracket(b1 rune, b2 rune) {
	panic('unbalanced `${b1}` found, its target `${b2}` is not known; address: ${state.address}, pc: ${state.pc}')
}

fn (mut state BFState) run() ? {
	mut i := 0
	// the BF interpreter starts here:
	for state.pc < state.program.len {
		// get the current program character (corresponding to our program counter), and interpret it according to BF's rules:
		instruction := state.program[state.pc]
		$if trace_execution ? {
			state.show('instruction ${i:08}: ${instruction:02x}, ${rune(instruction)}')
		}
		match instruction {
			`>` {
				state.address++ // increment the address
			}
			`<` {
				state.address-- // decrement the address
			}
			`+` {
				state.memory[state.address]++ // increment the value at the address
			}
			`-` {
				state.memory[state.address]-- // decrement the value at the address
			}
			`.` {
				print(rune(state.memory[state.address])) // print the value at the address
				flush_stdout() // ensure that even single characters are printed immediately, and not buffered
			}
			`,` {
				inp := u8(term.utf8_getchar() or { 0 }) // read a character value from the standard input/terminal
				state.memory[state.address] = inp
			}
			`[` {
				if state.memory[state.address] == 0 {
					state.pc = u16(state.targets[state.pc])
					continue
				}
			}
			`]` {
				if state.memory[state.address] != 0 {
					state.pc = u16(state.targets[state.pc])
					continue
				}
			}
			`#` {
				state.show('#')
			}
			else {
				// The interpreter should ignore characters that are not part of the language.
				// I.e. they are treated like programmer comments.
			}
		}

		i++
		// increment the program counter to go to the next instruction
		state.pc++
		// go back to the line `for state.pc < state.program.len {`
	}
}

@[noreturn]
fn show_usage() {
	eprintln('you need to supply a brainfuck program/expression as a string argument,')
	eprintln('or filename.b, if it is located in a file (note the `.b` or `.bf` extension).')
	exit(1) // exit with non-zero exit code if there is no program to run
}

fn main() {
	if os.args.len < 2 {
		show_usage()
	}
	mut program := os.args[1] // our program is fed in as a string
	if program.ends_with('.b') || program.ends_with('.bf') {
		program = os.read_file(program) or {
			eprintln('error reading file ${program}: ${err}')
			show_usage()
		}
	}

	mut state := BFState.new(program)
	state.run()

	if show_state {
		state.show('FINAL')
	}
}

// vtest build: !openbsd
import gg
import math
import rand
import sokol.audio
import os.asset
import sokol.sgl

const designed_width = 600
const designed_height = 800
const brick_width = 53
const brick_height = 20
const bevel_size = int(brick_height * 0.18)
const highlight_color = gg.rgba(255, 255, 255, 65)
const shade_color = gg.rgba(0, 0, 0, 65)

struct Brick {
mut:
	x     f32
	y     f32
	w     f32 = brick_width
	h     f32 = brick_height
	c     gg.Color
	value int
	alive bool = true
}

struct Game {
mut:
	width     int = designed_width
	height    int = designed_height
	ball_x    f32
	ball_y    f32
	ball_r    f32 = 10.0
	ball_dx   f32 = 4
	ball_dy   f32 = -4
	paddle_x  f32 = 250
	paddle_w  f32 = 100
	paddle_h  f32 = 20
	paddle_dx f32 = 8
	bricks    []Brick
	nbricks   int
	npaddles  int = 10
	npoints   int
	nlevels   int = 1
	nevent    int
	sound     SoundManager
	ctx       &gg.Context = unsafe { nil }
}

fn Game.new() &Game {
	mut g := &Game{}
	g.ball_x, g.ball_y = f32(g.width) / 2, f32(g.height) - g.paddle_h
	g.init_bricks()
	return g
}

enum SoundKind {
	paddle
	brick
	wall
	lose_ball
}

struct SoundManager {
mut:
	sounds      [4][]f32 // TODO: using map[SoundKind][]f32 here breaks emscripten; use map after the fix
	initialised bool
}

fn (mut sm SoundManager) init() {
	all_kinds := [SoundKind.paddle, .brick, .wall, .lose_ball]!
	sample_rate := f32(audio.sample_rate())
	duration, volume := 0.09, f32(.25)
	nframes := int(sample_rate * duration)
	for i in 0 .. nframes {
		t := f32(i) / sample_rate
		sm.sounds[int(SoundKind.paddle)] << volume * math.sinf(t * 936.0 * 2 * math.pi)
		sm.sounds[int(SoundKind.brick)] << volume * math.sinf(t * 432.0 * 2 * math.pi)
		sm.sounds[int(SoundKind.wall)] << volume * math.sinf(t * 174.0 * 2 * math.pi)
		sm.sounds[int(SoundKind.lose_ball)] << math.sinf(t * 123.0 * 2 * math.pi)
	}
	border_samples := 2000
	for k, s := f32(0), 0; s <= border_samples; k, s = k + 1.0 / f32(border_samples), s + 1 {
		rk := f32(1) - k
		rs := nframes - border_samples - 1 + s
		for kind in all_kinds {
			sm.sounds[int(kind)][s] *= k
			sm.sounds[int(kind)][rs] *= rk
		}
	}
	sm.initialised = true
}

fn (mut g Game) play(k SoundKind) {
	if g.sound.initialised {
		s := g.sound.sounds[int(k)]
		audio.push(s.data, s.len)
	}
}

fn (mut g Game) init_bricks() {
	yoffset, xoffset := f32(50 + rand.intn(100) or { 0 }), f32(0 + rand.intn(50) or { 0 })
	g.bricks.clear()
	g.nbricks = 0
	for row in 0 .. 10 {
		for col in 0 .. 10 {
			g.bricks << Brick{
				x:     col * (brick_width + 1) + xoffset
				y:     row * (brick_height + 1) + yoffset
				c:     gg.rgb(0x40 | rand.u8(), 0x40 | rand.u8(), 0x40 | rand.u8())
				value: 10 - row
			}
			g.nbricks++
		}
	}
	for _ in 0 .. 5 + rand.intn(10) or { 0 } {
		i := rand.intn(g.bricks.len - 1) or { 0 }
		if g.bricks[i].alive {
			g.bricks[i].alive = false
			g.nbricks--
		}
	}
}

fn (mut g Game) draw() {
	ws := gg.window_size()
	g.ctx.begin()
	sgl.push_matrix()
	sgl.scale(f32(ws.width) / f32(designed_width), f32(ws.height) / f32(designed_height), 0)

	g.draw_paddle()
	g.draw_ball()
	for brick in g.bricks {
		if brick.alive {
			g.draw_brick(brick)
		}
	}
	label1 := 'Level: ${g.nlevels:02}  Points: ${g.npoints:06}'
	label2 := 'Bricks: ${g.nbricks:03}  Paddles: ${g.npaddles:02}'
	g.ctx.draw_text(5, 3, label1, size: 24, color: gg.rgb(255, 255, 255))
	g.ctx.draw_text(320, 3, label2, size: 24, color: gg.rgb(255, 255, 255))

	sgl.pop_matrix()
	g.ctx.end()
}

fn (g &Game) draw_ball() {
	g.ctx.draw_circle_filled(g.ball_x, g.ball_y, g.ball_r, gg.red)
	mut ball_r_less := g.ball_r
	for _ in 0 .. 3 {
		ball_r_less *= 0.8
		g.ctx.draw_circle_filled(g.ball_x - g.ball_r + ball_r_less, g.ball_y - g.ball_r +
			ball_r_less, ball_r_less, highlight_color)
	}
}

fn (g &Game) draw_paddle() {
	roffset, rradius := -5, 18
	g.ctx.draw_circle_filled(g.paddle_x - roffset, g.height, rradius, gg.blue)
	g.ctx.draw_circle_filled(g.paddle_x + g.paddle_w + roffset, g.height, rradius, gg.blue)
	g.ctx.draw_rect_filled(g.paddle_x, g.height - g.paddle_h + 2, g.paddle_w, g.paddle_h, gg.blue)
	g.ctx.draw_rect_filled(g.paddle_x, g.height - g.paddle_h + 2, g.paddle_w, bevel_size,
		highlight_color)
}

fn (g &Game) draw_brick(brick Brick) {
	g.ctx.draw_rect_filled(brick.x, brick.y, brick.w, brick.h, brick.c)
	g.ctx.draw_rect_filled(brick.x, brick.y, brick.w, bevel_size, highlight_color)
	g.ctx.draw_rect_filled(brick.x, brick.y, bevel_size, brick.h - bevel_size, highlight_color)
	g.ctx.draw_rect_filled(brick.x + brick.w - bevel_size, brick.y, bevel_size,
		brick.h - bevel_size, shade_color)
	g.ctx.draw_rect_filled(brick.x, brick.y + brick.h - bevel_size, brick.w, bevel_size,
		shade_color)
}

fn (mut g Game) game_over() {
	g.init_bricks()
	g.npoints, g.nlevels, g.npaddles = 0, 1, 5
}

fn (mut g Game) goto_next_level() {
	g.init_bricks()
	g.npaddles++
	g.nlevels++
}

fn (mut g Game) move(k f32) {
	if k < 0 {
		if g.paddle_x <= 0 {
			return
		}
	} else if k > 0 {
		if g.paddle_x >= g.width - g.paddle_w {
			return
		}
	}
	g.paddle_x += k * g.paddle_dx
}

fn (mut g Game) update() {
	if g.ctx.pressed_keys[gg.KeyCode.left] {
		g.move(-1.0)
	}
	if g.ctx.pressed_keys[gg.KeyCode.right] {
		g.move(1.0)
	}
	//
	g.ball_x, g.ball_y = g.ball_x + g.ball_dx, g.ball_y + g.ball_dy
	// Wall collisions
	if g.ball_x < g.ball_r || g.ball_x > g.width - g.ball_r {
		g.ball_dx *= -1
		g.play(.wall)
	}
	if g.ball_y < g.ball_r {
		g.ball_dy *= -1
		g.play(.wall)
	}
	if g.ball_y > g.height {
		g.ball_x, g.ball_y = g.paddle_x + g.paddle_w / 2, f32(g.height) - g.paddle_h
		g.ball_dy = -4
		g.npaddles--
		g.play(.lose_ball)
		if g.npaddles <= 0 {
			g.game_over()
		}
	}
	// Paddle collision
	is_ball_on_paddle_y := g.ball_y + g.ball_r > g.height - g.paddle_h
		&& g.ball_y < g.height - g.ball_r
	is_ball_on_paddle_x := g.ball_x > g.paddle_x - 10 && g.ball_x < g.paddle_x + g.paddle_w + 10
	if is_ball_on_paddle_y && is_ball_on_paddle_x {
		g.play(.paddle)
		g.ball_dy = -math.abs(g.ball_dy)
		x_in_paddle := g.ball_x - g.paddle_x
		rmargin := 10
		if x_in_paddle < rmargin || x_in_paddle + rmargin > g.paddle_w {
			g.ball_dx *= -1
		} else if !(x_in_paddle > 40 && x_in_paddle < 60) {
			r := 10 * (-0.5 + rand.f32())
			g.ball_dx += r
			g.ball_dx = f32(int_min(int_max(-80, int(g.ball_dx * 10)), 80)) / 10
		}
	}
	// Brick collisions
	for mut brick in g.bricks {
		if brick.alive && g.ball_y - g.ball_r < brick.y + brick.h && g.ball_y + g.ball_r > brick.y
			&& g.ball_x + g.ball_r > brick.x && g.ball_x - g.ball_r < brick.x + brick.w {
			g.play(.brick)
			brick.alive = false
			g.nbricks--
			g.npoints += brick.value
			g.ball_dy *= -1
			if g.nbricks == 0 {
				g.goto_next_level()
			}
		}
	}
}

fn (mut g Game) touch_event(touch_point gg.TouchPoint) {
	ws := gg.window_size()
	tx := touch_point.pos_x
	if tx <= f32(ws.width) * 0.5 {
		g.move(-1.0)
	} else {
		g.move(1.0)
	}
}

@[if wasm32_emscripten]
fn (mut g Game) handle_event() {
	if g.nevent > 0 {
		return
	}
	// the audio has to be started when the wasm canvas has received user
	// interaction, unlike on desktop platforms
	audio.setup(buffer_frames: 1024)
	g.sound.init()
	g.nevent++
}

fn main() {
	mut g := Game.new()
	mut fpath := asset.get_path('../assets', 'fonts/RobotoMono-Regular.ttf')
	$if !wasm32_emscripten {
		audio.setup(buffer_frames: 512) // too small values lead to cracking sounds or no sound at all on macos
		g.sound.init()
		fpath = ''
	}
	g.ctx = gg.new_context(
		width:        g.width
		height:       g.height
		window_title: 'V Breakout'
		frame_fn:     fn (mut g Game) {
			dt := g.ctx.timer.elapsed().milliseconds()
			if dt > 15 {
				g.update()
				g.ctx.timer.restart()
			}
			g.draw()
		}
		click_fn:     fn (x f32, y f32, btn gg.MouseButton, mut g Game) {
			g.handle_event()
		}
		event_fn:     fn (e &gg.Event, mut g Game) {
			g.handle_event()
			if e.typ == .touches_began || e.typ == .touches_moved {
				if e.num_touches > 0 {
					touch_point := e.touches[0]
					g.touch_event(touch_point)
				}
			}
		}
		keydown_fn:   fn (key gg.KeyCode, _ gg.Modifier, mut g Game) {
			g.handle_event()
			match key {
				.r {
					g.game_over()
				}
				.escape {
					exit(0)
				}
				else {}
			}
		}
		user_data:    g
		font_path:    fpath
	)
	g.ctx.run()
}

// Simple raw HTTP head request
import net
import time
import io

fn main() {
	// Make a new connection
	mut conn := net.dial_tcp('google.com:80')!
	// Simple http HEAD request for a file
	conn.write_string('GET /index.html HTTP/1.0\r\n\r\n')!
	// Wrap in a buffered reader
	mut r := io.new_buffered_reader(reader: conn)
	for {
		l := r.read_line() or { break }
		println('${l}')
		// Make it nice and obvious that we are doing this line by line
		time.sleep(100 * time.millisecond)
	}
}

