module main

import encoding.cbor
import encoding.hex
import time

struct Address {
	street string
	city   string
	zip    string @[cbor: 'postal_code']
}

struct User {
	name      string
	age       u32
	email     ?string
	tags      []string
	address   Address
	signed_up time.Time
	internal  string @[skip]
}

fn main() {
	user := User{
		name:      'Alice'
		age:       30
		email:     'alice@example.com'
		tags:      ['admin', 'beta']
		address:   Address{
			street: '1 Test Lane'
			city:   'Paris'
			zip:    '75000'
		}
		signed_up: time.parse_iso8601('2025-01-15T10:00:00Z') or { time.now() }
		internal:  'will not be encoded'
	}

	// 1. Generic typed encode/decode
	bytes := cbor.encode[User](user, cbor.EncodeOpts{})!
	println('encoded ${bytes.len} bytes: ${hex.encode(bytes)}')

	back := cbor.decode[User](bytes, cbor.DecodeOpts{})!
	println('round-trip name=${back.name} age=${back.age} city=${back.address.city}')

	// 2. Canonical encoding for stable hashing/signing
	mut m := map[string]int{}
	m['z'] = 26
	m['a'] = 1
	m['m'] = 13
	canonical := cbor.encode[map[string]int](m, cbor.EncodeOpts{
		canonical: true
	})!
	println('canonical map: ${hex.encode(canonical)}')

	// 3. Decode an unknown payload into a Value tree
	v := cbor.decode[cbor.Value](bytes, cbor.DecodeOpts{})!
	if name_val := v.get('name') {
		if s := name_val.as_string() {
			println('peeked name from Value tree: ${s}')
		}
	}

	// 4. Manual streaming: build a CBOR array of mixed types
	mut p := cbor.new_packer(cbor.EncodeOpts{})
	p.pack_array_header(3)
	p.pack_uint(42)
	p.pack_text('hello')
	p.pack_bool(true)
	stream_bytes := p.bytes()
	println('manual stream: ${hex.encode(stream_bytes)}')

	mut up := cbor.new_unpacker(stream_bytes, cbor.DecodeOpts{})
	n := up.unpack_array_header()!
	first := up.unpack_uint()!
	second := up.unpack_text()!
	third := up.unpack_bool()!
	println('unpacked array of ${n}: ${first}, "${second}", ${third}')
}

module main

import cli { Command, Flag }
import os

fn main() {
	mut cmd := Command{
		name:        'cli'
		description: 'An example of the cli library.'
		version:     '1.0.0'
	}
	mut greet_cmd := Command{
		name:          'greet'
		description:   'Prints greeting in different languages.'
		usage:         '<name>'
		required_args: 1
		pre_execute:   greet_pre_func
		execute:       greet_func
		post_execute:  greet_post_func
	}
	greet_cmd.add_flag(Flag{
		flag:        .string
		required:    true
		name:        'language'
		abbrev:      'l'
		description: 'Language of the message.'
	})
	greet_cmd.add_flag(Flag{
		flag:          .int
		name:          'times'
		default_value: ['3']
		description:   'Number of times the message gets printed.'
	})
	greet_cmd.add_flag(Flag{
		flag:        .string_array
		name:        'fun'
		description: 'Just a dumby flags to show multiple.'
	})
	cmd.add_command(greet_cmd)
	cmd.setup()
	cmd.parse(os.args)
}

fn greet_func(cmd Command) ! {
	language := cmd.flags.get_string('language') or {
		panic('Failed to get `language` flag: ${err}')
	}
	times := cmd.flags.get_int('times') or { panic('Failed to get `times` flag: ${err}') }
	name := cmd.args[0]
	for _ in 0 .. times {
		match language {
			'english', 'en' {
				println('Welcome ${name}')
			}
			'german', 'de' {
				println('Willkommen ${name}')
			}
			'dutch', 'nl' {
				println('Welkom ${name}')
			}
			else {
				println('Unsupported language')
				println('Supported languages are `english`, `german` and `dutch`.')
				break
			}
		}
	}
	fun := cmd.flags.get_strings('fun') or { panic('Failed to get `fun` flag: ${err}') }
	for f in fun {
		println('fun: ${f}')
	}
}

fn greet_pre_func(_cmd Command) ! {
	println('This is a function running before the main function.\n')
}

fn greet_post_func(_cmd Command) ! {
	println('\nThis is a function running after the main function.')
}

// This example demonstrates the `vlib/cli` features that show up automatically
// in `--help` when you populate the optional `group`, `examples` and
// `learn_more` fields of `Command`. No opt-in is required — leaving any of
// them empty simply skips the corresponding section.
//
// Compile from the V repo root:
//   v -o tasky examples/cli_groups.v
//
// Try it out:
//   ./tasky --help          # root help with grouped commands and examples
//   ./tasky issue --help    # sub-command help with INHERITED FLAGS
//   ./tasky issue list -v
//   ./tasky version
module main

import cli
import os

fn main() {
	mut app := cli.Command{
		name:        'tasky'
		description: 'A tiny issue tracker CLI'
		version:     '0.1.0'
		posix_mode:  true
		examples:    [
			'\$ tasky issue list',
			'\$ tasky issue create --title "Fix CI"',
			'\$ tasky config get editor',
		]
		learn_more:  'Use `tasky <command> --help` for details about a command.\nDocumentation lives at https://example.test/tasky'
	}
	app.add_flag(cli.Flag{
		flag:        .string
		name:        'config'
		abbrev:      'c'
		description: 'Path to a tasky config file'
		global:      true
	})
	app.add_command(issue_command())
	app.add_command(config_command())
	app.setup()
	app.parse(os.args)
}

fn issue_command() cli.Command {
	return cli.Command{
		name:        'issue'
		description: 'Work with issues'
		group:       'Core commands'
		commands:    [
			cli.Command{
				name:        'list'
				description: 'List open issues'
				execute:     issue_list
				flags:       [
					cli.Flag{
						flag:        .bool
						name:        'verbose'
						abbrev:      'v'
						description: 'Show issue bodies in addition to titles'
					},
				]
			},
			cli.Command{
				name:        'create'
				description: 'Create a new issue'
				execute:     issue_create
				flags:       [
					cli.Flag{
						flag:        .string
						name:        'title'
						abbrev:      't'
						description: 'Title of the issue to create'
						required:    true
					},
				]
			},
		]
	}
}

fn config_command() cli.Command {
	return cli.Command{
		name:        'config'
		description: 'Read or write tasky settings'
		group:       'Additional commands'
		commands:    [
			cli.Command{
				name:          'get'
				description:   'Print the value of a config key'
				usage:         '<key>'
				required_args: 1
				execute:       config_get
			},
			cli.Command{
				name:          'set'
				description:   'Update a config key'
				usage:         '<key> <value>'
				required_args: 2
				execute:       config_set
			},
		]
	}
}

fn issue_list(cmd cli.Command) ! {
	verbose := cmd.flags.get_bool('verbose') or { false }
	println('Listing issues (verbose=${verbose})')
}

fn issue_create(cmd cli.Command) ! {
	title := cmd.flags.get_string('title')!
	println('Created issue: ${title}')
}

fn config_get(cmd cli.Command) ! {
	println('config get ${cmd.args[0]}')
}

fn config_set(cmd cli.Command) ! {
	println('config set ${cmd.args[0]} = ${cmd.args[1]}')
}

// An X11 clock modeled after https://en.wikipedia.org/wiki/Station_clock
// This is a small V example that was based off of the fireworks example.
// Written by Stefan Schroeder in 2021 for the v project examples.
// See LICENSE for license information.
import gg
import math
import time

// All coordinates are designed for a clock size of this many pixel.
// You cannot change the size of the clock by adjusting this value.
const design_size = 700
const center = 350

// Half the width of a tic-mark.
const tw = 9
// Height of a minute tic-mark. (hour is twice, 3-hour is thrice)
const th = 25
// Padding of tic-mark to window border
const tp = 10

const tic_color = gg.Color{
	r: 50
	g: 50
	b: 50
}
const hand_color = gg.black
const second_hand_color = gg.red

struct App {
	minutes_tic []f32 = [f32(center - tw), tp, center + tw, tp, center + tw, tp, center + tw,
		tp + 1 * th, center - tw, tp + 1 * th]
	hours_tic   []f32 = [f32(center - tw), tp, center + tw, tp, center + tw, tp, center + tw,
		tp + 2 * th, center - tw, tp + 2 * th]
	hours3_tic  []f32 = [f32(center - tw), tp, center + tw, tp, center + tw, tp, center + tw,
		tp + 3 * th, center - tw, tp + 3 * th]

	hour_hand   []f32 = [f32(329), 161, 350, 140, 371, 161, 371, 413, 329, 413]
	minute_hand []f32 = [f32(334.25), 40.25, 350, 24.5, 365.75, 40.25, 365.75, 427, 334.25, 427]
	second_hand []f32 = [f32(345.8), 38.5, 350, 34.3, 354.2000, 38.5, 358.75, 427, 341.25, 427]
mut:
	gg        &gg.Context = unsafe { nil }
	draw_flag bool        = true
	dpi_scale f32         = 1.0
}

fn on_frame(mut app App) {
	if !app.draw_flag {
		return
	}
	app.gg.begin()

	for i in 0 .. 60 { // draw minute tics
		draw_convex_poly_rotate(mut app.gg, app.dpi_scale, app.minutes_tic, tic_color, i * 6)
	}
	for i in 0 .. 12 { // hours
		draw_convex_poly_rotate(mut app.gg, app.dpi_scale, app.hours_tic, tic_color, i * 30)
	}
	for i in 0 .. 4 { // 3 hours
		draw_convex_poly_rotate(mut app.gg, app.dpi_scale, app.hours3_tic, tic_color, i * 90)
	}

	n := time.now()

	// draw hour hand
	i := f32(n.hour) + f32(n.minute) / 60.0
	draw_convex_poly_rotate(mut app.gg, app.dpi_scale, app.hour_hand, hand_color, i * 30)

	// draw minute hand
	mut j := f32(n.minute)
	if n.second == 59 { // make minute hand move smoothly
		j += f32(math.sin(f32(n.nanosecond) / 1e9 * math.pi / 2.0))
	}
	draw_convex_poly_rotate(mut app.gg, app.dpi_scale, app.minute_hand, hand_color, j * 6)

	// draw second hand with smooth transition
	k := f32(n.second) + f32(math.sin(f32(n.nanosecond) / 1e9 * math.pi / 2.0))
	draw_convex_poly_rotate(mut app.gg, app.dpi_scale, app.second_hand, second_hand_color,
		0 + k * 6)

	app.gg.end()
}

// Rotate a polygon round the centerpoint
@[manualfree]
fn draw_convex_poly_rotate(mut ctx gg.Context, dpi_scale f32, points []f32, c gg.Color, angle f32) {
	sa := math.sin(math.pi * angle / 180.0)
	ca := math.cos(math.pi * angle / 180.0)

	mut rotated_points := []f32{cap: points.len}
	for i := 0; i < points.len / 2; i++ {
		x := points[2 * i]
		y := points[2 * i + 1]
		xn := f32((x - center) * ca - (y - center) * sa)
		yn := f32((x - center) * sa + (y - center) * ca)
		rotated_points << (xn + center) * dpi_scale
		rotated_points << (yn + center) * dpi_scale
	}
	ctx.draw_convex_poly(rotated_points, c)
	unsafe { rotated_points.free() }
}

fn (mut app App) resize() {
	size := gg.window_size()
	// avoid calls when minimized
	if size.width < 2 && size.height < 2 {
		return
	}
	w := f32(size.width) / design_size
	h := f32(size.height) / design_size
	app.dpi_scale = if w < h { w } else { h }
}

fn on_event(e &gg.Event, mut app App) {
	match e.typ {
		.resized, .resumed {
			app.resize()
		}
		.iconified {
			app.draw_flag = false
		}
		.restored {
			app.draw_flag = true
			app.resize()
		}
		else {
			if e.typ == .key_down {
				match e.key_code {
					.q {
						println('Good bye.')
						// do we need to free anything here?
						app.gg.quit()
					}
					else {}
				}
			}
		}
	}
}

fn on_init(mut app App) {
	app.resize()
}

fn main() {
	println("Press 'q' to quit.")
	mut app := &App{}
	app.gg = gg.new_context(
		width:        design_size
		height:       design_size
		window_title: 'Clock!'
		bg_color:     gg.white
		user_data:    app
		frame_fn:     on_frame
		event_fn:     on_event
		init_fn:      on_init
	)
	app.gg.run()
}

// This example shows how to use V's compile time defines and values via the -d flag and $d() function.
//
// To change the default values below, pass compile flags to v using: `-d ident=<value>`
// Examples:
// ´´´
// v -d header -d pad=10 -d jobs=8 run d_compile_value.v
// v -d id="Bob" -d pad=2 -d pad_char='$' -d jobs=10 run d_compile_value.v
// ```

const pad = $d('pad', 5)
const pad_char = $d('pad_char', `-`)

const footer = '
Available compile time flags:
 -d pad=<i64>
 -d pad_char=<character>
 -d id="<string>"
 -d jobs=<i64>
 -d header=<bool>
You can turn this message off with:
 -d footer=false'

struct Job {
	id string = $d('id', 'Job') // adjust with `-d id="My ID"`
}

struct App {
	jobs [$d('jobs', 4)]Job // adjust fixed array size with `-d jobs=6`
}

// println_padded prints `str` to stdout with a padding.
// Padding length and padding character can be adjusted at compile time
// via `-d pad=1` and `-d pad_char=x`.
fn println_padded(str string) {
	for _ in 0 .. pad {
		print(rune(pad_char))
	}
	println(' ${str}')
}

fn main() {
	header := $d('header', false) // adjust header variable with `-d header=true` or simply `-d header`
	if header {
		println_padded('Compile Value Example')
	}

	app := App{}
	for i, job in app.jobs {
		println_padded('${job.id} ${i + 1}')
	}

	// Turn the footer message off using `-d footer=false`
	if $d('footer', true) {
		println(footer)
	}
}

struct App {}

fn (mut app App) method_one() {}

fn (mut app App) method_two() int {
	return 0
}

fn (mut app App) method_three(s string) string {
	return s
}

fn main() {
	$for method in App.methods {
		$if method.typ is fn ( string ) string {
			println('${method.name} IS `fn(string) string`')
		} $else {
			println('${method.name} is NOT `fn(string) string`')
		}
		$if method.return_type !is int {
			println('${method.name} does NOT return `int`')
		} $else {
			println('${method.name} DOES return `int`')
		}
		$if method.args[0].typ !is string {
			println("${method.name}'s first arg is NOT `string`")
		} $else {
			println("${method.name}'s first arg IS `string`")
		}
		// TODO: Double inversion, should this even be allowed?
		$if method.typ is fn ( ) {
			println('${method.name} IS a void method')
		} $else {
			println('${method.name} is NOT a void method')
		}
		println('')
	}
}

// An example deserializer implementation

struct User {
	name string
	age  int
}

fn main() {
	data := 'name=Alice\nage=18'
	user := decode[User](data)
	println(user)
}

fn decode[T](data string) T {
	mut result := T{}
	// compile-time `for` loop
	// T.fields gives an array of a field metadata type
	$for field in T.fields {
		$if field.typ is string {
			// $(string_expr) produces an identifier
			result.$(field.name) = get_string(data, field.name)
		} $else $if field.typ is int {
			result.$(field.name) = get_int(data, field.name)
		}
	}
	return result
}

fn get_string(data string, field_name string) string {
	for line in data.split_into_lines() {
		key_val := line.split('=')
		if key_val[0] == field_name {
			return key_val[1]
		}
	}
	return ''
}

fn get_int(data string, field string) int {
	return get_string(data, field).int()
}

