		children: [
			Child{
				name: 'abc'
			},
			Child{
				name: 'def'
			},
		]
	}
	sql db {
		insert par into Parent
	}!
	parent := sql db {
		select from Parent where id == 1
	}!
	eprintln(parent)
}

